const R={};

/* ---------- overview ---------- */
/* two-series line chart (deposits vs withdrawals) drawn from the real daily series returned by /api/admin/overview */
function lines2(days,a,b,n){
 a=a.slice(-n).map(Number);b=b.slice(-n).map(Number);days=days.slice(-n);if(!a.concat(b).some(x=>x>0))return`<div class="empty" style="padding:60px 10px">No completed deposits or withdrawals in the last ${n} days.</div>`;const w=640,h=240,pl=44,pb=26,pt=10,mx=Math.max(...a,...b,1),nice=(()=>{const p=10**Math.floor(Math.log10(mx));return Math.ceil(mx/p*2)/2*p||1})();
 const X=i=>pl+(a.length>1?i/(a.length-1):0)*(w-pl-8),Y=v=>pt+(h-pt-pb)*(1-v/nice);
 const path=s=>s.map((v,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1)).join('');
 const grid=[0,.25,.5,.75,1].map(t=>{const y=Y(nice*t);return`<line x1="${pl}" x2="${w-8}" y1="${y}" y2="${y}" stroke="#EEF0F3"/><text x="${pl-8}" y="${y+4}" text-anchor="end" font-size="10.5" fill="#9AA0AE">${nice*t>=1000?'$'+(nice*t/1000).toFixed(nice*t%1000?1:0)+'k':'$'+(nice*t).toFixed(nice<4?2:0)}</text>`}).join('');
 const step=Math.max(1,Math.ceil(a.length/6)),xl=days.map((d,i)=>i%step===0||i===a.length-1?`<text x="${X(i)}" y="${h-6}" text-anchor="middle" font-size="10.5" fill="#9AA0AE">${esc(d.slice(5))}</text>`:'').join('');
 return`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Deposits and withdrawals, last ${n} days" style="height:auto;aspect-ratio:${w}/${h}">${grid}${xl}<path d="${path(a)}L${X(a.length-1)} ${Y(0)}L${X(0)} ${Y(0)}Z" fill="#0B0C10" opacity=".05"/><path d="${path(b)}" fill="none" stroke="#9AA0AE" stroke-width="2" stroke-linejoin="round"/><path d="${path(a)}" fill="none" stroke="#0B0C10" stroke-width="2.2" stroke-linejoin="round"/></svg><div class="key"><span><i style="background:#0B0C10"></i>Deposits</span><span><i style="background:#9AA0AE"></i>Withdrawals</span></div>`}
const ago=s=>{if(!s)return'';const m=Math.max(0,Math.round((Date.now()-new Date(s))/60000));return m<1?'just now':m<60?m+'m ago':m<1440?Math.round(m/60)+'h ago':Math.round(m/1440)+'d ago'};
const optional=(perm,u)=>can(perm)?V.get(u).catch(e=>{if(e instanceof Stale)throw e;return null}):Promise.resolve(null);

