 const re=()=>{st.page=1;route()};
 const fq=$('#fq',v);fq.onchange=e=>{st.q=e.target.value.trim();re()};
 $$('[data-f]',v).forEach(s=>s.onchange=e=>{st[s.dataset.f]=e.target.value;re()});
 const rs=$('#creset',v);if(rs)rs.onclick=()=>{Q.users={};route()};
 /* CSV export of exactly the filtered set (server-side, permission-checked, audited) */
 const ex=$('#cexp',v);if(ex){ex.onclick=()=>{location.href='/api/admin/users/export.csv?'+qs('users',{page:1,size:20})}}
 /* row actions menu: one popover at a time, owned by this page node so it disappears with it */
 let pop=null;const closePop=()=>{if(pop){pop.remove();pop=null;$$('[data-menu][aria-expanded=true]',v).forEach(b=>b.setAttribute('aria-expanded','false'))}};
